<?php
namespace App\Filament\Resources\BankChecks\Tables;
use App\Models\BankCheck; use Filament\Actions\EditAction; use Filament\Tables\Columns\TextColumn; use Filament\Tables\Filters\SelectFilter; use Filament\Tables\Table;
class BankChecksTable { public static function configure(Table $t):Table{return $t->columns([
 TextColumn::make('document_number')->label('رقم المستند')->searchable()->sortable(),TextColumn::make('type')->label('النوع')->formatStateUsing(fn($s)=>BankCheck::typeOptions()[$s]??$s)->badge()->color(fn($s)=>$s===BankCheck::TYPE_INCOMING?'success':'warning'),TextColumn::make('check_number')->label('رقم الشيك')->searchable(),TextColumn::make('party')->label('العميل / المورد')->state(fn(BankCheck $r)=>$r->partyName())->searchable(false),TextColumn::make('due_date')->label('الاستحقاق')->date('Y/m/d')->sortable(),TextColumn::make('amount')->label('القيمة')->money('EGP')->sortable(),TextColumn::make('status')->label('الحالة')->formatStateUsing(fn($s)=>BankCheck::statusOptions()[$s]??$s)->badge()->color(fn($s)=>match($s){BankCheck::STATUS_COLLECTED,BankCheck::STATUS_CASHED=>'success',BankCheck::STATUS_RETURNED=>'danger',BankCheck::STATUS_CANCELLED=>'gray',default=>'warning'}),TextColumn::make('bankAccount.bank.name')->label('البنك')->placeholder('—'),
 ])->filters([SelectFilter::make('type')->label('النوع')->options(BankCheck::typeOptions()),SelectFilter::make('status')->label('الحالة')->options(BankCheck::statusOptions())])->defaultSort('due_date','desc')->recordActions([EditAction::make()]);} }